using System;using System.IO;using Foundation;using UIKit;
namespace ReuseSmokeIOS;
public static class Program {public static void Main(string[] args)=>UIApplication.Main(args,null,typeof(AppDelegate));}
[Register("AppDelegate")] public class AppDelegate:UIApplicationDelegate {public override bool FinishedLaunching(UIApplication app,NSDictionary options){var path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"reuse-result.txt");try {var result=ReuseSmoke.Checks.Run();File.WriteAllText(path,result);Console.WriteLine(result);}catch(Exception e){File.WriteAllText(path,"FAIL "+e);Console.WriteLine(e);}return true;}}